import { adjacentControl } from '../../keyboard/navigation.js'
import { calculatePaymentSummary } from '../../data/paymentCalculations.js'

export const BANK_OPTIONS = [
  { name: 'Easypaisa', logo: 'data:image/png;base64,' },
  { name: 'Meezan Bank', logo: 'data:image/png;base64,' },
  { name: 'Faysal Bank', logo: 'data:image/png;base64,' },
  { name: 'Allied Bank', logo: 'data:image/png;base64,' },
]

const money = (value) => `Rs. ${Number(value || 0).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`

export default function Payment({ total, payments, chequeDetails, bankDetails = {}, method = 'cash', onMethodChange, onChange, onChequeDetailsChange, onBankDetailsChange }) {
  const { totalReceived, uncoveredBalance, excessPayment } = calculatePaymentSummary(total, payments)
  const updateChequeDetails = (field, value) => onChequeDetailsChange({ ...chequeDetails, [field]: value })
  const updateBankDetails = (field, value) => onBankDetailsChange({ ...bankDetails, [field]: value })
  const preventDateStepping = (event) => {
    if (!['PageUp', 'PageDown', 'ArrowUp', 'ArrowDown'].includes(event.key)) return
    event.preventDefault()
    if (event.key === 'ArrowUp' || event.key === 'ArrowDown') {
      const current = event.currentTarget
      const scope = current?.closest('[data-keyboard-scope]')
      if (!scope) return
      const next = adjacentControl(scope, current, event.key === 'ArrowUp' ? -1 : 1)
      const discount = current.closest('main')?.querySelector('[data-sale-step="cart"] input[max]')
      ;(next || (event.key === 'ArrowDown' ? discount : null))?.focus()
    }
  }
  const amountField = method === 'bank' ? 'bank' : method === 'cheque' ? 'cheque' : 'cash'
  const amountInput = (field, label) => (
    <label className="flex flex-col gap-1.5 text-xs sm:text-sm font-semibold text-[#173b32]" htmlFor={`sale-payment-${field}`}>
      {label}
      <input
        id={`sale-payment-${field}`}
        name={`payment-${field}`}
        type="number"
        min="0"
        step="0.01"
        value={payments[field]}
        onChange={(event) => onChange(field, event.target.value)}
        className="w-full h-11 px-3.5 rounded-xl border border-[#dfe4dc] bg-white text-sm text-[#173b32] focus:outline-none focus:border-[#155b4b]"
      />
    </label>
  )

  return (
    <section data-keyboard-scope className="p-4 sm:p-6 lg:p-7 rounded-2xl bg-white border border-[#e2e6df] shadow-panel hover:border-[#155b4b]/20 hover:shadow-panel-hover transition-all space-y-4">
      <style>{`input[name="sale-payment-method"]:focus-visible { outline: none !important; }`}</style>
      <h2 className="text-[#173b32] text-lg sm:text-xl lg:text-2xl font-semibold leading-tight">Payment Details</h2>
      <p className="text-xs text-[#718078]">Amounts below apply to this sale only.</p>
      <dl className="grid grid-cols-1 sm:grid-cols-3 gap-3" aria-live="polite">
        {[["Total Sale Amount", total], ["Amount Paid", totalReceived], ["Remaining Customer Balance", uncoveredBalance]].map(([label, value]) => (
          <div key={label} className="min-w-0 p-3 rounded-xl bg-[#e8f2e3]">
            <dt className="text-xs text-[#557250]">{label}</dt>
            <dd className="mt-1 text-sm font-bold text-[#155b4b] tabular-nums break-words">{money(value)}</dd>
          </div>
        ))}
      </dl>

      <fieldset>
        <legend className="text-xs sm:text-sm font-semibold text-[#173b32] mb-2">Payment Method</legend>
        <div className="grid grid-cols-2 gap-2">
          {[["cash", "Cash"], ["bank", "Bank"], ["cheque", "Cheque"], ["split", "Split Payment"]].map(([value, label]) => (
            <label key={value} className={`flex items-center gap-2 p-3 rounded-xl border text-sm cursor-pointer focus-within:border-[#155b4b] ${method === value ? "border-[#155b4b] bg-[#e8f2e3] text-[#155b4b] font-semibold" : "border-[#dfe4dc] bg-white text-[#173b32]"}`}>
              <input type="radio" name="sale-payment-method" value={value} checked={method === value} onChange={() => onMethodChange(value)} onKeyDown={(event) => {
                if (event.key !== 'Enter' || event.isComposing || event.repeat || event.ctrlKey || event.altKey || event.metaKey || event.shiftKey || !['bank', 'split'].includes(value)) return
                event.preventDefault()
                const section = event.currentTarget.closest('[data-keyboard-scope]')
                onMethodChange(value)
                requestAnimationFrame(() => {
                  const group = section?.querySelector('[aria-label="Bank accounts"]')
                  const selected = group?.querySelector('button[aria-pressed="true"]')
                  ;(selected || group?.querySelector('button'))?.focus()
                })
              }} className="accent-[#155b4b]" />
              {label}
            </label>
          ))}
        </div>
      </fieldset>

<div className="space-y-4 lg:min-h-[540px]" style={{ overflowAnchor: 'none' }}>
      {method === 'split' ? (
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
          {amountInput('cash', 'Cash Amount')}
          {bankDetails.bankName ? amountInput('bank', 'Bank Amount') : <p className="text-xs text-[#718078] self-center">Select a bank below to enter its amount.</p>}
          {amountInput('cheque', 'Cheque Amount')}
        </div>
      ) : method !== 'bank' && amountInput(amountField, 'Amount Paid')}

      {(method === 'bank' || method === 'split') && (
        <fieldset className="space-y-3">
          <legend className="text-xs sm:text-sm font-semibold text-[#173b32] mb-2">Select Bank / Account</legend>
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-3" role="group" aria-label="Bank accounts" onKeyDown={(event) => {
            if (event.isComposing || event.ctrlKey || event.altKey || event.metaKey || event.shiftKey) return
            const directions = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 }
            const direction = directions[event.key]
            if (!direction) return
            const buttons = [...event.currentTarget.querySelectorAll('button')]
            const index = buttons.indexOf(event.target)
            if (index < 0) return
            event.preventDefault()
            buttons[(index + direction + buttons.length) % buttons.length]?.focus()
          }}>
            {BANK_OPTIONS.map((bank) => (
              <button
                key={bank.name}
                type="button"
                aria-pressed={bankDetails.bankName === bank.name}
                onClick={() => {
                  onBankDetailsChange({ bankName: bank.name, accountNumber: bankDetails.bankName === bank.name ? bankDetails.accountNumber || '' : '' })
                  requestAnimationFrame(() => document.getElementById('sale-payment-bank')?.focus())
                }}
                className={`flex flex-col items-center justify-center gap-2 p-3 rounded-xl border-2 min-h-28 cursor-pointer transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#155b4b] ${bankDetails.bankName === bank.name ? 'border-[#155b4b] bg-[#e8f2e3]' : 'border-[#dfe4dc] bg-white hover:border-[#155b4b]/50'}`}
              >
                <img src={bank.logo} alt="" className="h-14 w-full object-contain" />
                <span className="text-xs sm:text-sm font-semibold text-[#173b32]">{bank.name}</span>
              </button>
            ))}
          </div>
          {bankDetails.bankName && (
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 p-3 rounded-xl bg-[#f8faf4] border border-[#dfe4dc]">
              {method === 'bank' && amountInput('bank', `Amount to Pay — ${bankDetails.bankName}`)}
              {method === 'split' && <p className="text-sm font-semibold text-[#155b4b] self-center">Bank payment: {bankDetails.bankName}</p>}
              <label className="flex flex-col gap-1.5 text-xs sm:text-sm font-semibold text-[#173b32]" htmlFor="sale-bank-account">
                Account (optional)
                <input id="sale-bank-account" name="bankAccount" value={bankDetails.accountNumber || ''} onChange={(event) => updateBankDetails('accountNumber', event.target.value)} placeholder={`${bankDetails.bankName} account number or name`} className="w-full h-11 px-3.5 rounded-xl border border-[#dfe4dc] bg-white text-sm font-normal text-[#173b32] focus:outline-none focus:border-[#155b4b]" />
              </label>
            </div>
          )}
        </fieldset>
      )}

      {(method === 'cheque' || method === 'split') && (
        <fieldset className="grid grid-cols-1 sm:grid-cols-2 gap-3">
          <legend className="text-xs sm:text-sm font-semibold text-[#173b32] mb-2 sm:col-span-2">Cheque Details</legend>
          <label className="flex flex-col gap-1.5 text-xs sm:text-sm font-semibold text-[#173b32]" htmlFor="sale-cheque-number">Cheque Number
            <input id="sale-cheque-number" value={chequeDetails.chequeNumber} onChange={(event) => updateChequeDetails('chequeNumber', event.target.value)} className="w-full h-11 px-3.5 rounded-xl border border-[#dfe4dc] bg-white text-sm font-normal text-[#173b32] focus:outline-none focus:border-[#155b4b]" />
          </label>
          <label className="flex flex-col gap-1.5 text-xs sm:text-sm font-semibold text-[#173b32]" htmlFor="sale-cheque-bank">Cheque Bank
            <input id="sale-cheque-bank" value={chequeDetails.bankName} onChange={(event) => updateChequeDetails('bankName', event.target.value)} className="w-full h-11 px-3.5 rounded-xl border border-[#dfe4dc] bg-white text-sm font-normal text-[#173b32] focus:outline-none focus:border-[#155b4b]" />
          </label>
          <label className="flex flex-col gap-1.5 text-xs sm:text-sm font-semibold text-[#173b32]" htmlFor="sale-cheque-date">Cheque Date
            <input id="sale-cheque-date" type="date" onKeyDown={preventDateStepping} value={chequeDetails.chequeDate} onChange={(event) => updateChequeDetails('chequeDate', event.target.value)} className="w-full h-11 px-3.5 rounded-xl border border-[#dfe4dc] bg-white text-sm font-normal text-[#173b32] focus:outline-none focus:border-[#155b4b]" />
          </label>
          <label className="flex flex-col gap-1.5 text-xs sm:text-sm font-semibold text-[#173b32]" htmlFor="sale-cheque-due-date">Due / Clearing Date (optional)
            <input id="sale-cheque-due-date" type="date" onKeyDown={preventDateStepping} value={chequeDetails.dueDate} onChange={(event) => updateChequeDetails('dueDate', event.target.value)} className="w-full h-11 px-3.5 rounded-xl border border-[#dfe4dc] bg-white text-sm font-normal text-[#173b32] focus:outline-none focus:border-[#155b4b]" />
          </label>
        </fieldset>
      )}

      </div>

      {excessPayment > 0 && (
        <p className="mt-3 p-3 rounded-lg bg-red-50 border border-red-200 text-red-700 text-xs sm:text-sm font-semibold" role="alert">
          Payment exceeds bill total by {money(excessPayment)}
        </p>
      )}

    </section>
  )
}
